import { ImageResponse } from "next/og";

export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

/**
 * The site-wide fallback social card. Per-gown cards (the real og:image
 * for /gowns/[slug]) are generated by the image pipeline (KBS-13) from
 * the hero photograph's 1200x630 JPEG crop — this covers every other
 * route.
 */
export default function OpengraphImage() {
  return new ImageResponse(
    (
      <div
        style={{
          fontSize: 64,
          background: "#fff",
          color: "#111",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        Klei Bridal Studio
      </div>
    ),
    { ...size },
  );
}
